class Solution:
    def largestPrime(self, n):
        if n < 2:
            return 0
        is_p = [True] * (n + 1)
        is_p[0] = is_p[1] = False
        for i in range(2, int(n ** 0.5) + 1):
            if is_p[i]:
                for j in range(i * i, n + 1, i):
                    is_p[j] = False
        s = 0
        ans = 0
        for p in range(2, n + 1):
            if is_p[p]:
                s += p
                if s > n:
                    break
                if is_p[s]:
                    ans = s
        return ans

