class Solution {
public:
    int largestPrime(int n) {
        if (n < 2) return 0;
        vector<bool> isp(n + 1, true);
        isp[0] = isp[1] = false;
        for (int i = 2; (long long)i * i <= n; i++)
            if (isp[i])
                for (long long j = (long long)i * i; j <= n; j += i)
                    isp[j] = false;
        long long s = 0;
        int ans = 0;
        for (int p = 2; p <= n; p++) {
            if (isp[p]) {
                s += p;
                if (s > n) break;
                if (isp[s]) ans = s;
            }
        }
        return ans;
    }
};

