class Solution {
    public int largestPrime(int n) {
        if (n < 2) return 0;
        boolean[] isp = new boolean[n + 1];
        Arrays.fill(isp, true);
        isp[0] = isp[1] = false;
        for (int i = 2; (long) i * i <= n; i++)
            if (isp[i])
                for (long j = (long) i * i; j <= n; j += i)
                    isp[(int) j] = false;
        long s = 0;
        int ans = 0;
        for (int p = 2; p <= n; p++) {
            if (isp[p]) {
                s += p;
                if (s > n) break;
                if (isp[(int) s]) ans = (int) s;
            }
        }
        return ans;
    }
}

